'use strict';

/**
 * WhatsApp Business Cloud API  ⇄  Google Gemini
 * ----------------------------------------------------------------------------
 * A production-ready webhook server that answers WhatsApp text messages with
 * replies generated by `gemini-2.5-flash` through the official `@google/genai`
 * SDK, and delivers them back with the WhatsApp Cloud API (Graph API).
 *
 * Request flow
 *   Meta -> GET  /webhook   (verification handshake)
 *   Meta -> POST /webhook   (message payload)  -> 200 OK immediately
 *                                            \-> Gemini -> Graph API -> user
 *
 * Environment: see `.env.example`.
 */

const crypto = require('node:crypto');
const express = require('express');
const dotenv = require('dotenv');
const { GoogleGenAI } = require('@google/genai');

dotenv.config({ quiet: true });

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum number of characters WhatsApp accepts in a single text body. */
const WHATSAPP_TEXT_LIMIT = 4096;

/** How long a processed WhatsApp message id is remembered to drop retries. */
const DEDUPE_TTL_MS = 10 * 60 * 1000;
const DEDUPE_MAX_ENTRIES = 5000;

/** Graph API retry policy (only for 429 / 5xx / network failures). */
const GRAPH_API_MAX_ATTEMPTS = 3;
const GRAPH_API_RETRY_BASE_DELAY_MS = 500;
const RETRYABLE_STATUS_CODES = new Set([429, 500, 502, 503, 504]);

const DEFAULT_SYSTEM_PROMPT = [
  'You are a friendly, helpful assistant chatting on WhatsApp.',
  'Keep answers concise (under 120 words) and easy to read on a phone screen.',
  'Use plain text with short paragraphs; avoid Markdown tables and code fences',
  'unless the user explicitly asks for code.',
  'Never invent facts — if you do not know something, say so plainly.',
].join(' ');

const FALLBACK_REPLY =
  "Sorry, I couldn't generate a reply just now. Please try again in a moment.";

const LOG_LEVELS = Object.freeze({ error: 0, warn: 1, info: 2, debug: 3 });

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
  }
}

function parseBoolean(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') {
    return fallback;
  }
  return ['1', 'true', 'yes', 'on'].includes(String(value).trim().toLowerCase());
}

function parseInteger(value, fallback, { min, max }) {
  const parsed = Number.parseInt(String(value ?? '').trim(), 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(Math.max(parsed, min), max);
}

/**
 * Reads and validates configuration from the environment.
 * Throws {@link ConfigError} when a required variable is missing so the
 * process fails fast instead of erroring on the first webhook call.
 *
 * @param {NodeJS.ProcessEnv} [env=process.env]
 */
function loadConfig(env = process.env) {
  const required = [
    'GEMINI_API_KEY',
    'WHATSAPP_TOKEN',
    'PHONE_NUMBER_ID',
    'VERIFY_TOKEN',
  ];

  const missing = required.filter((key) => !String(env[key] ?? '').trim());
  if (missing.length > 0) {
    throw new ConfigError(
      `Missing required environment variable(s): ${missing.join(', ')}. ` +
        'Copy .env.example to .env and fill in the values.',
    );
  }

  const read = (key) => String(env[key] ?? '').trim();

  return Object.freeze({
    port: parseInteger(env.PORT, 3000, { min: 0, max: 65535 }),
    geminiApiKey: read('GEMINI_API_KEY'),
    geminiModel: read('GEMINI_MODEL') || 'gemini-2.5-flash',
    // 0 disables "thinking" on gemini-2.5-flash (much lower latency); -1 = automatic.
    geminiThinkingBudget: parseInteger(env.GEMINI_THINKING_BUDGET, 0, {
      min: -1,
      max: 32768,
    }),
    whatsappToken: read('WHATSAPP_TOKEN'),
    phoneNumberId: read('PHONE_NUMBER_ID'),
    verifyToken: read('VERIFY_TOKEN'),
    // Optional but strongly recommended in production: enables X-Hub-Signature-256 checks.
    appSecret: read('WHATSAPP_APP_SECRET') || null,
    graphApiVersion: read('GRAPH_API_VERSION') || 'v25.0',
    systemPrompt: read('SYSTEM_PROMPT') || DEFAULT_SYSTEM_PROMPT,
    maxHistoryTurns: parseInteger(env.MAX_HISTORY_TURNS, 20, { min: 1, max: 100 }),
    sessionTtlMs:
      parseInteger(env.SESSION_TTL_MINUTES, 30, { min: 1, max: 1440 }) * 60 * 1000,
    sendReadReceipts: parseBoolean(env.SEND_READ_RECEIPTS, false),
    requestTimeoutMs: parseInteger(env.REQUEST_TIMEOUT_MS, 30000, {
      min: 1000,
      max: 120000,
    }),
    logLevel: read('LOG_LEVEL').toLowerCase() || 'info',
  });
}

// ---------------------------------------------------------------------------
// Logging
// ---------------------------------------------------------------------------

function serializeError(error) {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      ...(error.status ? { status: error.status } : {}),
      ...(error.details ? { details: error.details } : {}),
      ...(error.stack ? { stack: error.stack.split('\n').slice(0, 4).join(' | ') } : {}),
    };
  }
  return { message: String(error) };
}

/**
 * Minimal JSON logger. Message bodies and credentials are never logged;
 * call sites pass only ids, sizes and error metadata.
 */
function createLogger(level = 'info') {
  const threshold = LOG_LEVELS[String(level).toLowerCase()] ?? LOG_LEVELS.info;

  const emit = (levelName, message, meta) => {
    if (LOG_LEVELS[levelName] > threshold) return;
    const record = { ts: new Date().toISOString(), level: levelName, msg: message };
    if (meta && Object.keys(meta).length > 0) Object.assign(record, meta);
    const line = JSON.stringify(record);
    if (levelName === 'error') console.error(line);
    else if (levelName === 'warn') console.warn(line);
    else console.log(line);
  };

  return {
    level,
    error: (message, meta) => emit('error', message, meta),
    warn: (message, meta) => emit('warn', message, meta),
    info: (message, meta) => emit('info', message, meta),
    debug: (message, meta) => emit('debug', message, meta),
  };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function delay(ms) {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

function safeJsonParse(value) {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

/** Constant-time comparison of two strings (avoids leaking token length/prefix). */
function safeCompare(a, b) {
  const bufA = Buffer.from(String(a), 'utf8');
  const bufB = Buffer.from(String(b), 'utf8');
  return bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB);
}

/**
 * Validates Meta's `X-Hub-Signature-256` header against the raw request body.
 * @param {Buffer|undefined} rawBody
 * @param {string|undefined} headerValue e.g. "sha256=ab12..."
 * @param {string} appSecret
 */
function isValidSignature(rawBody, headerValue, appSecret) {
  if (!Buffer.isBuffer(rawBody) || !appSecret) return false;
  if (typeof headerValue !== 'string' || !headerValue.startsWith('sha256=')) {
    return false;
  }
  const provided = Buffer.from(headerValue.slice('sha256='.length), 'hex');
  const expected = crypto.createHmac('sha256', appSecret).update(rawBody).digest();
  return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
}

/**
 * Splits a long reply into WhatsApp-sized chunks, preferring paragraph, line,
 * sentence and word boundaries over cutting words in half.
 *
 * @param {string} text
 * @param {number} [limit=WHATSAPP_TEXT_LIMIT]
 * @returns {string[]}
 */
function splitMessage(text, limit = WHATSAPP_TEXT_LIMIT) {
  const normalized = String(text ?? '').replace(/\r\n/g, '\n').trim();
  if (!normalized) return [];
  if (normalized.length <= limit) return [normalized];

  const minUsefulCut = Math.floor(limit * 0.5);
  const delimiters = ['\n\n', '\n', '. ', '! ', '? ', ' '];
  const chunks = [];
  let remaining = normalized;

  while (remaining.length > limit) {
    const window = remaining.slice(0, limit);
    let cut = null;

    for (const delimiter of delimiters) {
      const index = window.lastIndexOf(delimiter);
      if (index >= minUsefulCut) {
        cut = index + delimiter.length;
        break;
      }
    }

    if (cut === null) cut = limit;

    const chunk = remaining.slice(0, cut).trim();
    if (chunk) chunks.push(chunk);
    remaining = remaining.slice(cut).trim();
  }

  if (remaining) chunks.push(remaining);
  return chunks;
}

/** Bounded, TTL-based cache used to drop duplicate webhook deliveries. */
function createMessageCache({ ttlMs = DEDUPE_TTL_MS, maxEntries = DEDUPE_MAX_ENTRIES } = {}) {
  const entries = new Map();

  const prune = (now) => {
    for (const [key, expiresAt] of entries) {
      if (expiresAt <= now) entries.delete(key);
    }
    while (entries.size > maxEntries) {
      entries.delete(entries.keys().next().value);
    }
  };

  return {
    /** Returns true when the id was already seen; marks it as seen otherwise. */
    seen(id) {
      if (!id) return false;
      const now = Date.now();
      const expiresAt = entries.get(id);
      if (expiresAt && expiresAt > now) return true;
      if (expiresAt) entries.delete(id);
      entries.set(id, now + ttlMs);
      if (entries.size > maxEntries / 2) prune(now);
      return false;
    },
  };
}

/**
 * Flattens a Cloud API payload into the messages that need a reply.
 * Tolerates missing/partial entries instead of throwing.
 *
 * @returns {Array<Record<string, any>>}
 */
function extractMessages(payload, logger) {
  if (!payload || typeof payload !== 'object') return [];

  const messages = [];
  const entries = Array.isArray(payload.entry) ? payload.entry : [];

  for (const entry of entries) {
    const changes = Array.isArray(entry?.changes) ? entry.changes : [];
    for (const change of changes) {
      const value = change?.value;
      if (!value || typeof value !== 'object') continue;

      // Errors reported by Meta for this WABA / phone number.
      if (Array.isArray(value.errors) && value.errors.length > 0) {
        for (const error of value.errors) {
          logger.warn('webhook:meta-error', {
            code: error?.code ?? null,
            title: error?.title ?? null,
            message: error?.message ?? null,
          });
        }
      }

      // Delivery/read receipts arrive here — nothing to answer.
      if (Array.isArray(value.statuses) && value.statuses.length > 0) {
        logger.debug('webhook:status-update-ignored', { count: value.statuses.length });
      }

      const incoming = Array.isArray(value.messages) ? value.messages : [];
      for (const message of incoming) {
        if (message && typeof message === 'object') messages.push(message);
      }
    }
  }

  return messages;
}

// ---------------------------------------------------------------------------
// Gemini
// ---------------------------------------------------------------------------

/**
 * Creates the reply generator. One Gemini chat session is kept per WhatsApp
 * number so conversations stay multi-turn, bounded by `maxHistoryTurns`.
 *
 * @returns {((args: { userId: string, text: string }) => Promise<string|null>) & { dispose: () => void }}
 */
function createGeminiResponder({ config, logger, client }) {
  const ai = client ?? new GoogleGenAI({ apiKey: config.geminiApiKey });

  const generationConfig = {
    systemInstruction: config.systemPrompt,
    temperature: 0.7,
    maxOutputTokens: 1024,
    ...(Number.isFinite(config.geminiThinkingBudget)
      ? { thinkingConfig: { thinkingBudget: config.geminiThinkingBudget } }
      : {}),
    httpOptions: { timeout: config.requestTimeoutMs },
  };

  /** @type {Map<string, { chat: any, lastUsedAt: number }>} */
  const sessions = new Map();

  const startChat = (history) =>
    ai.chats.create({
      model: config.geminiModel,
      config: generationConfig,
      ...(history && history.length > 0 ? { history } : {}),
    });

  const getSession = (userId) => {
    const existing = sessions.get(userId);
    if (existing) {
      existing.lastUsedAt = Date.now();
      return existing;
    }
    const session = { chat: startChat(), lastUsedAt: Date.now() };
    sessions.set(userId, session);
    return session;
  };

  /**
   * Drops the oldest turns once the conversation exceeds `maxHistoryTurns`.
   * Keeps the history starting with a user turn, as the SDK requires.
   */
  const trimHistory = (session) => {
    const history = session.chat.getHistory(true);
    const maxEntries = config.maxHistoryTurns * 2;
    if (history.length <= maxEntries) return;

    const trimmed = history.slice(history.length - maxEntries);
    while (trimmed.length > 0 && trimmed[0].role !== 'user') trimmed.shift();
    session.chat = startChat(trimmed);
  };

  const evictExpiredSessions = () => {
    const now = Date.now();
    for (const [userId, session] of sessions) {
      if (now - session.lastUsedAt > config.sessionTtlMs) sessions.delete(userId);
    }
  };

  // Sweep idle conversations; unref() so it never keeps the process alive.
  const sweeper = setInterval(evictExpiredSessions, Math.min(config.sessionTtlMs, 5 * 60 * 1000));
  if (typeof sweeper.unref === 'function') sweeper.unref();

  const generateReply = async ({ userId, text }) => {
    const session = getSession(userId);
    const startedAt = Date.now();

    logger.debug('gemini:request', {
      userId,
      model: config.geminiModel,
      chars: text.length,
      activeSessions: sessions.size,
    });

    const response = await session.chat.sendMessage({ message: text });
    trimHistory(session);

    const reply = String(response.text ?? '').trim();
    const usage = response.usageMetadata ?? {};

    if (!reply) {
      logger.warn('gemini:empty-reply', {
        userId,
        blockReason: response.promptFeedback?.blockReason ?? null,
      });
      return null;
    }

    logger.info('gemini:reply', {
      userId,
      latencyMs: Date.now() - startedAt,
      chars: reply.length,
      promptTokens: usage.promptTokenCount ?? null,
      outputTokens: usage.candidatesTokenCount ?? null,
    });

    return reply;
  };

  generateReply.dispose = () => clearInterval(sweeper);
  return generateReply;
}

// ---------------------------------------------------------------------------
// WhatsApp Cloud API (Graph API)
// ---------------------------------------------------------------------------

class WhatsAppApiError extends Error {
  constructor(message, { status, details } = {}) {
    super(message);
    this.name = 'WhatsAppApiError';
    this.status = status;
    this.details = details;
  }
}

/**
 * Creates a WhatsApp sender bound to `PHONE_NUMBER_ID`.
 * Uses the native `fetch` available in Node.js 22 — no extra HTTP dependency.
 */
function createWhatsAppClient({ config, logger, fetchImpl = globalThis.fetch }) {
  const messagesUrl = `https://graph.facebook.com/${config.graphApiVersion}/${config.phoneNumberId}/messages`;

  const post = async (payload) => {
    let lastError = null;

    for (let attempt = 1; attempt <= GRAPH_API_MAX_ATTEMPTS; attempt += 1) {
      const startedAt = Date.now();

      try {
        const response = await fetchImpl(messagesUrl, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${config.whatsappToken}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(payload),
          signal: AbortSignal.timeout(config.requestTimeoutMs),
        });

        const raw = await response.text();

        if (response.ok) {
          logger.debug('whatsapp:sent', {
            type: payload.type ?? payload.status ?? 'unknown',
            attempt,
            latencyMs: Date.now() - startedAt,
          });
          return raw ? safeJsonParse(raw) : null;
        }

        lastError = new WhatsAppApiError(
          `WhatsApp Graph API responded with ${response.status}`,
          { status: response.status, details: raw.slice(0, 2000) },
        );

        if (
          !RETRYABLE_STATUS_CODES.has(response.status) ||
          attempt === GRAPH_API_MAX_ATTEMPTS
        ) {
          logger.error('whatsapp:api-error', {
            status: response.status,
            attempt,
            details: lastError.details,
          });
          throw lastError;
        }

        logger.warn('whatsapp:api-retry', { status: response.status, attempt });
      } catch (error) {
        if (error instanceof WhatsAppApiError) throw error;

        // Network failure or client-side timeout — retry with backoff.
        lastError = error;
        if (attempt === GRAPH_API_MAX_ATTEMPTS) {
          logger.error('whatsapp:network-error', {
            attempt,
            error: serializeError(error),
          });
          throw error;
        }
        logger.warn('whatsapp:network-retry', {
          attempt,
          error: serializeError(error),
        });
      }

      await delay(GRAPH_API_RETRY_BASE_DELAY_MS * 2 ** (attempt - 1));
    }

    throw lastError ?? new Error('Sending the WhatsApp message failed');
  };

  return {
    /** Sends a plain text message to a WhatsApp number (E.164 without "+"). */
    async sendText({ to, text }) {
      let body = String(text ?? '').trim();
      if (!body) throw new Error('Refusing to send an empty WhatsApp message');
      if (body.length > WHATSAPP_TEXT_LIMIT) {
        logger.warn('whatsapp:text-truncated', { length: body.length });
        body = body.slice(0, WHATSAPP_TEXT_LIMIT);
      }

      return post({
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to,
        type: 'text',
        text: { preview_url: false, body },
      });
    },

    /** Marks an inbound message as read and shows a typing indicator. */
    async markAsRead(messageId) {
      return post({
        messaging_product: 'whatsapp',
        status: 'read',
        message_id: messageId,
        typing_indicator: { type: 'text' },
      });
    },
  };
}

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------

/**
 * Builds the Express app with the two webhook routes plus health checks.
 * All collaborators are injected so the app can be tested without network I/O.
 */
function createApp({ config, logger, generateReply, whatsapp }) {
  const app = express();
  const dedupe = createMessageCache();

  app.disable('x-powered-by');
  // Meta (and ngrok) terminate TLS in front of the app.
  app.set('trust proxy', true);

  app.use(
    express.json({
      limit: '1mb',
      // Accept any JSON value (Meta always sends an object) so a stray `null`
      // or array body is still acked instead of triggering a webhook retry.
      strict: false,
      // Raw bytes are required to verify X-Hub-Signature-256.
      verify: (req, _res, buffer) => {
        if (buffer?.length) req.rawBody = buffer;
      },
    }),
  );

  // --- Health / info -------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({
      status: 'ok',
      uptimeSeconds: Math.round(process.uptime()),
      model: config.geminiModel,
    });
  });

  app.get('/', (_req, res) => {
    res.status(200).json({
      name: 'whatsapp-gemini-bot',
      endpoints: ['GET /webhook', 'POST /webhook', 'GET /health'],
    });
  });

  // --- 1. Webhook verification (Meta handshake) ---------------------------
  app.get('/webhook', (req, res) => {
    const mode = req.query['hub.mode'];
    const token = req.query['hub.verify_token'];
    const challenge = req.query['hub.challenge'];

    if (mode !== 'subscribe') {
      logger.warn('webhook:verify-bad-mode', { mode: typeof mode === 'string' ? mode : null });
      return res.status(400).type('text/plain').send('Unsupported mode');
    }

    if (typeof token !== 'string' || !safeCompare(token, config.verifyToken)) {
      logger.warn('webhook:verify-failed', { ip: req.ip });
      return res.sendStatus(403);
    }

    logger.info('webhook:verified');
    const echo = Array.isArray(challenge) ? challenge[0] : challenge;
    return res.status(200).type('text/plain').send(typeof echo === 'string' ? echo : '');
  });

  // --- Background message processing ------------------------------------

  const processPayload = async (payload) => {
    const messages = extractMessages(payload, logger);
    if (messages.length === 0) {
      logger.debug('webhook:no-messages');
      return;
    }

    for (const message of messages) {
      if (dedupe.seen(message.id)) {
        logger.info('webhook:duplicate-ignored', { messageId: message.id ?? null });
        continue;
      }
      await handleMessage(message);
    }
  };

  const handleMessage = async (message) => {
    const from = typeof message.from === 'string' ? message.from : null;
    if (!from) {
      logger.warn('message:skipped', { reason: 'missing-sender' });
      return;
    }

    // Only plain text is answered; statuses, reactions, media and unsupported
    // types are ignored so the bot cannot crash or answer its own messages.
    if (message.type !== 'text') {
      logger.info('message:skipped', {
        reason: 'non-text',
        type: message.type ?? 'unknown',
        userId: from,
      });
      return;
    }

    const text = typeof message.text?.body === 'string' ? message.text.body.trim() : '';
    if (!text) {
      logger.info('message:skipped', { reason: 'empty-text', userId: from });
      return;
    }

    // Never log message contents — only metadata. WhatsApp is a private channel.
    logger.info('message:received', {
      userId: from,
      messageId: message.id ?? null,
      chars: text.length,
    });

    if (config.sendReadReceipts && message.id) {
      try {
        await whatsapp.markAsRead(message.id);
      } catch (error) {
        // Non-fatal: a missing blue tick must never block the reply.
        logger.warn('whatsapp:read-receipt-failed', { error: serializeError(error) });
      }
    }

    let reply = null;
    try {
      reply = await generateReply({ userId: from, text, messageId: message.id });
    } catch (error) {
      logger.error('gemini:request-failed', {
        userId: from,
        error: serializeError(error),
      });
      reply = FALLBACK_REPLY;
    }

    const chunks = splitMessage(reply ?? FALLBACK_REPLY, WHATSAPP_TEXT_LIMIT);
    for (const [index, chunk] of chunks.entries()) {
      try {
        await whatsapp.sendText({ to: from, text: chunk });
      } catch (error) {
        logger.error('whatsapp:send-failed', {
          userId: from,
          chunk: index + 1,
          chunks: chunks.length,
          error: serializeError(error),
        });
        break;
      }
    }
  };

  // --- 2. Incoming messages ----------------------------------------------
  app.post('/webhook', (req, res) => {
    if (config.appSecret) {
      const signature = req.get('x-hub-signature-256');
      if (!isValidSignature(req.rawBody, signature, config.appSecret)) {
        logger.warn('webhook:invalid-signature', { ip: req.ip });
        return res.status(401).json({ error: 'Invalid signature' });
      }
    }

    // Ack Meta *immediately* so it stops retrying; Gemini + Graph API calls
    // run in the background. Errors there are logged, never propagated.
    res.status(200).type('text/plain').send('EVENT_RECEIVED');

    setImmediate(() => {
      processPayload(req.body).catch((error) => {
        logger.error('webhook:processing-failed', { error: serializeError(error) });
      });
    });
  });

  // --- Errors & 404 -------------------------------------------------------
  app.use((_req, res) => {
    res.status(404).json({ error: 'Not found' });
  });

  app.use((error, req, res, next) => {
    if (res.headersSent) return next(error);

    if (error?.type === 'entity.parse.failed' || error instanceof SyntaxError) {
      logger.warn('request:invalid-json', { path: req.path });
      return res.status(400).json({ error: 'Invalid JSON body' });
    }

    logger.error('request:unhandled-error', {
      path: req.path,
      error: serializeError(error),
    });
    return res.status(500).json({ error: 'Internal server error' });
  });

  return app;
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

async function main() {
  const config = loadConfig();
  const logger = createLogger(config.logLevel);

  const whatsapp = createWhatsAppClient({ config, logger });
  const generateReply = createGeminiResponder({ config, logger });
  const app = createApp({ config, logger, generateReply, whatsapp });

  const server = app.listen(config.port, '0.0.0.0', () => {
    logger.info('server:listening', {
      port: config.port,
      node: process.version,
      model: config.geminiModel,
      graphApiVersion: config.graphApiVersion,
      signatureVerification: Boolean(config.appSecret),
    });
    logger.info('server:ready', {
      webhook: `http://localhost:${config.port}/webhook`,
      health: `http://localhost:${config.port}/health`,
    });
  });

  server.requestTimeout = 30_000;
  server.headersTimeout = 35_000;
  server.keepAliveTimeout = 65_000;

  let shuttingDown = false;
  const shutdown = (signal) => {
    if (shuttingDown) return;
    shuttingDown = true;
    logger.info('server:shutdown', { signal });

    generateReply.dispose();
    server.close(() => {
      logger.info('server:closed');
      process.exit(0);
    });
    // Do not hang forever on keep-alive connections.
    setTimeout(() => process.exit(1), 10_000).unref();
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));

  process.on('unhandledRejection', (reason) => {
    logger.error('process:unhandled-rejection', { error: serializeError(reason) });
  });

  process.on('uncaughtException', (error) => {
    logger.error('process:uncaught-exception', { error: serializeError(error) });
    shutdown('uncaughtException');
  });

  return server;
}

if (require.main === module) {
  main().catch((error) => {
    if (error instanceof ConfigError) {
      console.error(`[startup] ${error.message}`);
    } else {
      console.error('[startup] Failed to start server:', error);
    }
    process.exit(1);
  });
}

module.exports = {
  main,
  loadConfig,
  createLogger,
  createApp,
  createGeminiResponder,
  createWhatsAppClient,
  splitMessage,
  extractMessages,
  isValidSignature,
  safeCompare,
  createMessageCache,
  ConfigError,
  WhatsAppApiError,
  FALLBACK_REPLY,
  DEFAULT_SYSTEM_PROMPT,
  WHATSAPP_TEXT_LIMIT,
};
